// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {VaultAdapter} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    VaultAdapter c;

    bytes32 constant IMPLEMENTATION_SLOT = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;
    bytes32 constant BEACON_SLOT = 0xa3f0ad74e5423aebfd80d3ef4346578335a9a72aeaee59ff6cb3582b35133d50;

    function setUp() public { c = new VaultAdapter(); }

    function testFuzz_property(uint256 salt, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(salt != 0 || true); // keep domain wide; any salt is admissible
        vm.prank(actor);
        bytes32 returned = c.proxiableUUID();
        // General rule: proxiableUUID always exposes the implementation slot, never the beacon slot.
        assertTrue(returned == IMPLEMENTATION_SLOT && returned != BEACON_SLOT);
    }
}
